from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanValidationV2(SchemaObject):
    id = SchemaField(name="id", not_null=True)
    is_completed = SchemaField(name="is_completed", not_null=True)
    links = SchemaField(name="links", not_null=True)

    def __init__(self, id, is_completed, links):
        self.id = id
        self.is_completed = is_completed
        self.links = links

        super(PlanValidationV2, self).__init__()
